/**
 * DESIGN.md → design tokens.
 *
 * Reads the YAML front matter (colors, typography, rounded, spacing, components) and the
 * "Elevation & Depth" shadow levels from the prose, then writes:
 *   apps/web/src/styles/tokens.css  — Tailwind v4 `@theme` block (CSS variables + utilities)
 *   apps/web/src/styles/tokens.ts   — the same values as a typed object for TS code
 * DESIGN.md stays the single source; never edit the generated files by hand.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse } from 'yaml';

type TypeStyle = {
  fontFamily: string;
  fontSize: string;
  fontWeight: number;
  lineHeight: string;
  letterSpacing?: string;
  fontFeature?: string;
};

export interface DesignTokens {
  colors: Record<string, string>;
  typography: Record<string, TypeStyle>;
  rounded: Record<string, string>;
  spacing: Record<string, string>;
  components: Record<string, Record<string, string | number>>;
  shadows: Record<string, string>;
}

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');

export function parseDesign(markdown: string): DesignTokens {
  const match = /^---\n([\s\S]*?)\n---/.exec(markdown);
  if (!match?.[1]) throw new Error('DESIGN.md has no YAML front matter');
  const fm = parse(match[1]) as Omit<DesignTokens, 'shadows'>;

  const shadows: Record<string, string> = {};
  for (const [, level, value] of markdown.matchAll(/\*\*Level (\d):\*\*\s*`([^`]+)`/g)) {
    if (level && value) shadows[level] = value;
  }
  if (Object.keys(shadows).length === 0) throw new Error('No elevation levels found in DESIGN.md');

  return { ...fm, shadows };
}

/** Resolve "{colors.action}" style references against the token set. */
export function resolveRef(tokens: DesignTokens, value: string | number): string | number {
  if (typeof value !== 'string') return value;
  const [, groupName, key] = /^\{(\w+)\.([\w-]+)\}$/.exec(value) ?? [];
  if (!groupName || !key) return value;
  const group = (tokens as unknown as Record<string, Record<string, unknown>>)[groupName];
  const hit = group?.[key];
  if (hit === undefined) throw new Error(`Unresolved token reference ${value}`);
  return typeof hit === 'object' ? value : (hit as string | number);
}

export function resolvedComponents(tokens: DesignTokens) {
  const out: Record<string, Record<string, string | number>> = {};
  for (const [name, props] of Object.entries(tokens.components)) {
    out[name] = Object.fromEntries(Object.entries(props).map(([k, v]) => [k, resolveRef(tokens, v)]));
  }
  return out;
}

export function buildCss(tokens: DesignTokens): string {
  const lines: string[] = [
    '/* GENERATED by scripts/tokens.ts from DESIGN.md — do not edit. Run `pnpm tokens`. */',
    '@theme static {',
    '  /* Only DESIGN.md colours exist: Tailwind defaults are cleared. */',
    '  --color-*: initial;',
  ];
  for (const [name, hex] of Object.entries(tokens.colors)) lines.push(`  --color-${name}: ${hex};`);

  lines.push('', '  --font-sans: var(--font-inter), ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;');
  for (const [name, t] of Object.entries(tokens.typography)) {
    lines.push(`  --text-${name}: ${t.fontSize};`);
    lines.push(`  --text-${name}--line-height: ${t.lineHeight};`);
    lines.push(`  --text-${name}--font-weight: ${t.fontWeight};`);
    if (t.letterSpacing) lines.push(`  --text-${name}--letter-spacing: ${t.letterSpacing};`);
  }

  lines.push('', '  --radius-*: initial;');
  for (const [name, v] of Object.entries(tokens.rounded)) lines.push(`  --radius-${name}: ${v};`);

  lines.push('', '  /* 4px base grid: p-1 = 4px, p-4 = 16px … plus named steps (p-md = 16px). */', '  --spacing: 4px;');
  for (const [name, v] of Object.entries(tokens.spacing)) lines.push(`  --spacing-${name}: ${v};`);

  lines.push('', '  --shadow-*: initial;');
  for (const [level, v] of Object.entries(tokens.shadows)) lines.push(`  --shadow-${level}: ${v};`);

  lines.push('', '  --ease-standard: cubic-bezier(0, 0, 0.2, 1);', '}', '');
  return lines.join('\n');
}

export function buildTs(tokens: DesignTokens): string {
  const data = {
    colors: tokens.colors,
    typography: tokens.typography,
    rounded: tokens.rounded,
    spacing: tokens.spacing,
    shadows: tokens.shadows,
    components: resolvedComponents(tokens),
  };
  return (
    '// GENERATED by scripts/tokens.ts from DESIGN.md — do not edit. Run `pnpm tokens`.\n' +
    `export const tokens = ${JSON.stringify(data, null, 2)} as const;\n\n` +
    'export type ColorToken = keyof typeof tokens.colors;\n'
  );
}

function main() {
  const tokens = parseDesign(readFileSync(resolve(root, 'DESIGN.md'), 'utf8'));
  resolvedComponents(tokens); // throws on any broken reference
  const outDir = resolve(root, 'apps/web/src/styles');
  writeFileSync(resolve(outDir, 'tokens.css'), buildCss(tokens));
  writeFileSync(resolve(outDir, 'tokens.ts'), buildTs(tokens));
  console.log(
    `tokens: ${Object.keys(tokens.colors).length} colours, ${Object.keys(tokens.typography).length} type styles, ` +
      `${Object.keys(tokens.components).length} components → apps/web/src/styles/tokens.{css,ts}`,
  );
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
